package com.autosphere.controller;
import com.autosphere.model.*;import com.autosphere.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/admin") public class AdminController {private final VehicleRepository vehicles;private final CityPriceRepository prices;public AdminController(VehicleRepository v,CityPriceRepository p){vehicles=v;prices=p;}public record VehicleInput(@NotBlank String stockId,@NotBlank String type,@NotBlank String model,String variant,String fuel,int year,long kilometres,@Positive long exShowroomPrice,String imageUrl,String description,Integer owners,String registrationMasked,String inspectionReport,String colours,java.time.LocalDate priceValidUntil,String priceChangeNote){}@PostMapping("/vehicles") public Vehicle add(@Valid @RequestBody VehicleInput r){Vehicle v=new Vehicle();v.stockId=r.stockId();v.type=r.type();v.model=r.model();v.variant=r.variant();v.fuel=r.fuel();v.year=r.year();v.kilometres=r.kilometres();v.exShowroomPrice=r.exShowroomPrice();v.imageUrl=r.imageUrl();v.description=r.description();v.owners=r.owners()==null?1:r.owners();v.registrationMasked=r.registrationMasked()==null?"UP-**-****":r.registrationMasked();v.inspectionReport=r.inspectionReport()==null?"Inspection report pending admin upload.":r.inspectionReport();v.colours=r.colours()==null?"White, Silver, Black":r.colours();v.priceValidUntil=r.priceValidUntil()==null?java.time.LocalDate.now().plusDays(15):r.priceValidUntil();v.priceChangeNote=r.priceChangeNote()==null?"Indicative price; confirm with showroom before purchase.":r.priceChangeNote();return vehicles.save(v);}@PutMapping("/vehicles/{id}") public Vehicle update(@PathVariable Long id,@Valid @RequestBody VehicleInput r){Vehicle v=vehicles.findById(id).orElseThrow();v.stockId=r.stockId();v.type=r.type();v.model=r.model();v.variant=r.variant();v.fuel=r.fuel();v.year=r.year();v.kilometres=r.kilometres();v.exShowroomPrice=r.exShowroomPrice();v.imageUrl=r.imageUrl();v.description=r.description();if(r.owners()!=null)v.owners=r.owners();if(r.registrationMasked()!=null)v.registrationMasked=r.registrationMasked();if(r.inspectionReport()!=null)v.inspectionReport=r.inspectionReport();if(r.colours()!=null)v.colours=r.colours();if(r.priceValidUntil()!=null)v.priceValidUntil=r.priceValidUntil();if(r.priceChangeNote()!=null)v.priceChangeNote=r.priceChangeNote();return vehicles.save(v);}@PutMapping("/vehicles/{id}/status") public Vehicle status(@PathVariable Long id,@RequestBody Map<String,String> r){Vehicle v=vehicles.findById(id).orElseThrow();v.status=r.getOrDefault("status",v.status);return vehicles.save(v);}public record PriceInput(@NotBlank String city,@PositiveOrZero long roadTax,@PositiveOrZero long insurance,@PositiveOrZero long accessories,java.time.LocalDate validUntil,String changeNote){}@PutMapping("/pricing/{vehicleId}") public CityPrice setPrice(@PathVariable Long vehicleId,@Valid @RequestBody PriceInput r){Vehicle v=vehicles.findById(vehicleId).orElseThrow();CityPrice p=prices.findByVehicleIdAndCityIgnoreCase(vehicleId,r.city()).orElse(new CityPrice(v,r.city(),0,0,0));p.roadTax=r.roadTax();p.insurance=r.insurance();p.accessories=r.accessories();if(r.validUntil()!=null)v.priceValidUntil=r.validUntil();if(r.changeNote()!=null)v.priceChangeNote=r.changeNote();vehicles.save(v);return prices.save(p);}}
